+		return -EFAULT;
+	}
+
+	if (otx2_open(pfvf->netdev)) {
+		netdev_err(netdev, "Failed to start the device\n");
+		pfvf->flags &= ~OTX2_FLAG_PER_Q_RATE_LIMIT_ENABLED;
+		return -EFAULT;
+	}
+
+	for (tc = 0; tc < qopt->num_tc; tc++) {
